"use client";
import{useCallback,useEffect,useMemo,useState}from"react";import{AppShell}from"../ui/app-shell";import{getSupabaseBrowserClient}from"../../lib/supabase/client";import{usePlayerData}from"../../lib/use-player-data";import{fileChecksum,parseTrackmanCsv,type TrackmanParseResult}from"../../lib/trackman-import";import"../trackman.css";
type Player={id:string;display_name:string|null;email:string};type ImportRecord={id:string;file_name:string;created_at:string;accepted_rows:number;status:string;trackman_sessions:{title:string;session_date:string|null;review_status?:string;test_type?:string}|null};
export default function TrackmanImportPage(){const{profile}=usePlayerData();const coach=profile?.role==="coach"||profile?.role==="admin";const[players,setPlayers]=useState<Player[]>([]),[playerId,setPlayerId]=useState(""),[file,setFile]=useState<File|null>(null),[parsed,setParsed]=useState<TrackmanParseResult|null>(null),[checksum,setChecksum]=useState(""),[busy,setBusy]=useState(false),[message,setMessage]=useState(""),[title,setTitle]=useState(""),[date,setDate]=useState(""),[location,setLocation]=useState(""),[testType,setTestType]=useState("standard"),[practiceNote,setPracticeNote]=useState(""),[submitReview,setSubmitReview]=useState(true),[imports,setImports]=useState<ImportRecord[]>([]);
 const load=useCallback(async()=>{const sb=getSupabaseBrowserClient();if(!sb||!profile)return;if(coach){const{data:links}=await sb.from("coach_player_links").select("player_id").eq("coach_id",profile.id);const ids=(links||[]).map(x=>x.player_id);if(ids.length){const{data}=await sb.from("profiles").select("id,display_name,email").in("id",ids).order("display_name");const rows=(data||[])as Player[];setPlayers(rows);setPlayerId(current=>current||rows[0]?.id||"")}}else{setPlayers([{id:profile.id,display_name:profile.display_name,email:profile.email}]);setPlayerId(profile.id)}const{data}=await sb.from("trackman_imports").select("id,file_name,created_at,accepted_rows,status,trackman_sessions(title,session_date,review_status,test_type)").order("created_at",{ascending:false}).limit(10);setImports((data||[])as unknown as ImportRecord[])},[profile,coach]);useEffect(()=>{const timer=setTimeout(()=>void load(),0);return()=>clearTimeout(timer)},[load]);
 const inspect=useCallback(async(selected:File)=>{if(!selected.name.toLowerCase().endsWith(".csv")){setMessage("Please choose a TrackMan CSV file.");return}setFile(selected);setBusy(true);setMessage("");setParsed(null);try{const text=await selected.text();const[result,hash]=await Promise.all([parseTrackmanCsv(text),fileChecksum(selected)]);setParsed(result);setChecksum(hash);setTitle(selected.name.replace(/\.csv$/i,""));setMessage(`${result.shots.length} valid shots staged. Review the summary before importing.`)}catch(error){setMessage(error instanceof Error?error.message:"The file could not be read.")}finally{setBusy(false)}},[]);
 useEffect(()=>{const zone=()=>document.querySelector<HTMLElement>(".file-drop");const paint=(active:boolean)=>zone()?.classList.toggle("drag-active",active);const inside=(event:DragEvent)=>Boolean((event.target as Element|null)?.closest?.(".file-drop"));const over=(event:DragEvent)=>{if(!inside(event))return;event.preventDefault();if(event.dataTransfer)event.dataTransfer.dropEffect="copy";paint(true)};const leave=(event:DragEvent)=>{if(inside(event)&&!(event.relatedTarget as Element|null)?.closest?.(".file-drop"))paint(false)};const drop=(event:DragEvent)=>{if(!inside(event))return;event.preventDefault();paint(false);const selected=event.dataTransfer?.files?.[0];if(selected)void inspect(selected)};window.addEventListener("dragenter",over);window.addEventListener("dragover",over);window.addEventListener("dragleave",leave);window.addEventListener("drop",drop);return()=>{window.removeEventListener("dragenter",over);window.removeEventListener("dragover",over);window.removeEventListener("dragleave",leave);window.removeEventListener("drop",drop)}},[inspect]);
 const importFile=async()=>{const sb=getSupabaseBrowserClient();if(!sb||!file||!parsed||!playerId)return;setBusy(true);setMessage("");const{data,error}=await sb.rpc("import_trackman_csv",{payload:{player_id:playerId,file_name:file.name,file_sha256:checksum,header_row:parsed.headerRow,headers:parsed.headers,title,session_date:date||null,location:location||null,test_type:testType,practice_note:practiceNote,submit_for_review:submitReview,rejected_rows:parsed.rejected.length,metadata:{client_file_size:file.size,client_last_modified:new Date(file.lastModified).toISOString(),warnings:parsed.warnings,rejected:parsed.rejected},shots:parsed.shots}});if(error)setMessage(error.message);else if(data?.status==="duplicate")setMessage("Duplicate upload detected. This file has already been imported, so no shots were added.");else setMessage(`${data?.inserted||0} shots imported${submitReview?" and submitted for coach review":""}${data?.duplicates?`; ${data.duplicates} duplicate shots skipped`:""}.`);setBusy(false);await load()};const mappedFields=useMemo(()=>parsed?Object.keys(parsed.shots[0]?.values||{}).length:0,[parsed]);
 return <AppShell active="trackman"><header className="page-heading"><div><p className="eyebrow">Package 7G.5 · TrackMan practice upload</p><h1>Bring every practice shot into view.</h1><p>{coach?"Upload for a linked player or review player-submitted practice sessions.":"Upload your own TrackMan CSV, add the practice context and submit the measured results to your coach."} Missing optional tiles remain blank and original values are retained.</p></div></header>{message&&<div className="success-banner" role="status">{message}</div>}<section className="trackman-grid"><div className="tm-panel"><div className="section-heading"><div><p className="eyebrow">1 · Source file</p><h2>Drop, stage and validate</h2></div></div><label className="file-drop"><input type="file" accept=".csv,text/csv" onChange={event=>{const selected=event.target.files?.[0];if(selected)void inspect(selected)}}/><strong>{busy?"Reading file…":file?.name||"Drop CSV here or choose file"}</strong><span>TrackMan CSV · optional columns and blank values accepted</span></label>{parsed&&<><div className="tm-metrics"><div><strong>{parsed.shots.length}</strong><span>valid shots</span></div><div><strong>{parsed.headers.length}</strong><span>source columns</span></div><div><strong>{mappedFields}</strong><span>mapped fields</span></div><div><strong>{parsed.rejected.length}</strong><span>rejected rows</span></div></div>{parsed.warnings.length>0&&<div className="tm-warnings"><strong>Optional data not supplied</strong>{parsed.warnings.map(item=><span key={item}>{item}</span>)}</div>}<details><summary>View source columns</summary><div className="column-cloud">{parsed.headers.map(header=><span key={header}>{header}</span>)}</div></details></>}</div><div className="tm-panel"><div className="section-heading"><div><p className="eyebrow">2 · Practice context</p><h2>Create session</h2></div></div><div className="tm-form"><label>Player<select disabled={!coach} value={playerId} onChange={event=>setPlayerId(event.target.value)}><option value="">Choose linked player</option>{players.map(player=><option key={player.id} value={player.id}>{player.display_name||player.email}</option>)}</select></label><label>Session title<input value={title} onChange={event=>setTitle(event.target.value)}/></label><div className="split"><label>Practice type<select value={testType} onChange={event=>setTestType(event.target.value)}><option value="standard">Practice</option><option value="baseline">Baseline</option><option value="no_aid">No-aid test</option><option value="transfer">Transfer test</option><option value="retest">Retest</option></select></label><label>Session date<input type="date" value={date} onChange={event=>setDate(event.target.value)}/></label></div><label>Location<input value={location} onChange={event=>setLocation(event.target.value)} placeholder="Optional"/></label><label>Practice note<textarea value={practiceNote} onChange={event=>setPracticeNote(event.target.value)} placeholder="What were you working on? What did you notice?"/></label><label className="tm-check"><input type="checkbox" checked={submitReview} onChange={event=>setSubmitReview(event.target.checked)}/>Submit this session for coach review</label><button className="primary-action" disabled={!parsed?.shots.length||!playerId||busy} onClick={importFile}>{busy?"Working…":"Import validated shots"}</button><small>Measured values cannot be edited. Uploading the same file again will not duplicate its shots.</small></div></div></section><section className="tm-history"><div className="section-heading"><div><p className="eyebrow">Practice history</p><h2>Recent imports</h2></div></div>{imports.map(item=><div className="tm-history-row" key={item.id}><div><strong>{item.trackman_sessions?.title||item.file_name}</strong><span>{item.file_name} · {item.trackman_sessions?.test_type?.replace("_"," ")||"practice"}</span></div><span>{item.trackman_sessions?.session_date||new Date(item.created_at).toLocaleDateString()}</span><b>{item.accepted_rows} shots</b><em>{item.trackman_sessions?.review_status?.replace("_"," ")||item.status}</em></div>)}{!imports.length&&<p className="empty-copy">No TrackMan files imported yet.</p>}</section></AppShell>}
